import{_ as e,o as a,c as o,a3 as i}from"./chunks/framework.D3oaa6bG.js";const u=JSON.parse('{"title":"Shipping methods","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/shipping-methods.md","filePath":"guide/usage/shipping-methods.md","lastUpdated":null}'),r={name:"guide/usage/shipping-methods.md"};function s(h,t,n,l,d,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="shipping-methods" tabindex="-1">Shipping methods <a class="header-anchor" href="#shipping-methods" aria-label="Permalink to &quot;Shipping methods&quot;">​</a></h1><p><code>Shipping methods</code> are presented to a customer during checkout.</p><p>You can add certain restrictions on the availability of a shipping method. If during checkout only one method is available it will be automatically set. If multiple methods are available the customer can choose between them.</p><p>Make sure that you&#39;ve got a shipping method available for all possible cases so your customers won&#39;t hit a dead end during checkout.</p><h2 id="country-restrictions" tabindex="-1">Country restrictions <a class="header-anchor" href="#country-restrictions" aria-label="Permalink to &quot;Country restrictions&quot;">​</a></h2><p>You can restrict a shipping method to certain countries. If a restriction is set, the method will be only available for shipping to one of the selected countries. If no countries are selected the method will be available worldwide.</p><h2 id="cart-total-restrictions" tabindex="-1">Cart total restrictions <a class="header-anchor" href="#cart-total-restrictions" aria-label="Permalink to &quot;Cart total restrictions&quot;">​</a></h2><p>You can restrict a method to only be available above or below a certain cart total. This feature enables you to offer a &quot;Free Shipping&quot; method above a certain total.</p><p>Don&#39;t forget to set the availability limits for both shipping methods if you want to use this feature. This way the correct shipping method will be set automatically during checkout since only one will be available.</p><table tabindex="0"><thead><tr><th>Method</th><th>Available below</th><th>Available above</th></tr></thead><tbody><tr><td>Default shipping</td><td>100 USD</td><td></td></tr><tr><td>Free shipping</td><td></td><td>100 USD</td></tr></tbody></table><h2 id="rates-weight" tabindex="-1">Rates (Weight) <a class="header-anchor" href="#rates-weight" aria-label="Permalink to &quot;Rates (Weight)&quot;">​</a></h2><p>You can create multiple rates to increase or decrease the shipping method&#39;s cost depending on the total weight of an order.</p><p>To use this feature make sure to add <code>weight</code> information to each product. Products without a weight property will be calculated as 0 gramms.</p>',13)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
